import {build} from 'esbuild';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
const path='packages/flutter_core/assets/communications/audio-bridge.js';
const result=await build({entryPoints:['packages/shared/src/communications/flutter-audio-bridge.mjs'],bundle:true,format:'iife',target:'es2022',minify:false,write:false,legalComments:'none'});
const content='// Generated by tools/communication-media-bundle.mjs; do not edit.\n'+result.outputFiles[0].text;
if(process.argv.includes('--generate')){mkdirSync('packages/flutter_core/assets/communications',{recursive:true});writeFileSync(path,content);}
else if(readFileSync(path,'utf8')!==content)throw Error('Shared browser media asset differs from source');
console.log('Shared browser media asset matches the inherited session source');
